q = """SELECT ?t ?item ?inc ?mfrLabel ?ctryLabel WHERE { VALUES ?t { %s } ?a schema:about ?item; schema:isPartOf <https://en.wikipedia.org/>; schema:name ?t.
OPTIONAL{?item wdt:P571 ?inc} OPTIONAL{?item wdt:P176 ?mfr} OPTIONAL{?item wdt:P17 ?ctry}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". } }""" % vals
print(q)
